prototype_script:
import { createRequire } from 'node:module';
import { readFile, writeFile } from 'node:fs/promises';
import { relative, resolve } from 'node:path';
const require = createRequire(import.meta.url);
const { build } = require(require.resolve('esbuild', { paths: [require.resolve('tsx')] }));
const mode = process.argv[2] ?? 'source';
const root = resolve('dist');
const start = performance.now();
const result = await build({
  entryPoints: ['dist/cli.js'], outdir: 'dist', entryNames: `cli-${mode}`, chunkNames: `experiment-${mode}-[hash]`, bundle: true, splitting: true,
  platform: 'node', format: 'esm', target: 'node20', treeShaking: true, keepNames: true,
  packages: mode === 'source' ? 'external' : undefined,
  external: ['better-sqlite3', 'ssh2', 'react-devtools-core', 'react', 'jiti', '@anthropic-ai/sandbox-runtime', '@qduc/agent-wire'],
  banner: { js: `import { createRequire as bundleCreateRequire } from 'node:module'; const require = bundleCreateRequire(import.meta.url);` },
  metafile: true,
  plugins: [{ name: 'preserve-module-locations', setup(b) {
    b.onLoad({ filter: /\.js$/ }, async ({ path }) => {
      if (!path.startsWith(root + '/')) return;
      const contents = (await readFile(path, 'utf8')).replaceAll('import.meta.url',
        `new URL(${JSON.stringify('./' + relative(root, path))}, import.meta.url).href`).replaceAll('import.meta.dirname',
        `bundleFileURLToPath(new URL(${JSON.stringify('./' + relative(root, resolve(path, '..')) + '/')}, import.meta.url))`);
      return { contents: `import { fileURLToPath as bundleFileURLToPath } from 'node:url';\n` + contents.replace(/^#!.*\n/, ''), loader: 'js' };
    });
  } }],
});
await writeFile(`/tmp/term2-bundle-${mode}-meta.json`, JSON.stringify(result.metafile));
console.log(JSON.stringify({ mode, seconds: (performance.now() - start) / 1000, inputs: Object.keys(result.metafile.inputs).length }));
